package main

// Golden tests: testdata/golden/*.json were generated by the Node.js plugin
// (the implementation this Go port replaced) from the same inputs, so these
// tests hold the port to its exact behaviour: TOML parsing and errors,
// palettes, species, config, agent matching, animation, night, process
// labels, pane order, the managed block and the configure command's output,
// byte for byte.

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"
	"time"
)

func loadGolden(t *testing.T, name string) any {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "golden", name))
	if err != nil {
		t.Fatal(err)
	}
	v, err := decodeOrdered(b)
	if err != nil {
		t.Fatal(err)
	}
	return v
}

// generic: v as decoded JSON (ordered tables, float64 numbers, non-finite
// numbers as {"__num__": "NaN"} like the generator wrote them).
func generic(t *testing.T, v any) any {
	switch x := v.(type) {
	case *Table:
		out := NewTable()
		for _, k := range x.Keys() {
			e, _ := x.Get(k)
			out.Set(k, generic(t, e))
		}
		return out
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			out[i] = generic(t, e)
		}
		return out
	case float64:
		if math.IsNaN(x) || math.IsInf(x, 0) {
			n := NewTable()
			n.Set("__num__", jsNumber(x))
			return n
		}
		return x
	case string, bool, nil:
		return x
	}
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("marshal %T: %v", v, err)
	}
	g, err := decodeOrdered(b)
	if err != nil {
		t.Fatal(err)
	}
	return generic(t, g)
}

// diff: "" when equal; ordered also compares table key order.
func diff(path string, a, b any, ordered bool) string {
	switch x := a.(type) {
	case *Table:
		y, ok := b.(*Table)
		if !ok {
			return fmt.Sprintf("%s: table vs %T", path, b)
		}
		ka, kb := append([]string(nil), x.Keys()...), append([]string(nil), y.Keys()...)
		if !ordered {
			sort.Strings(ka)
			sort.Strings(kb)
		}
		if !reflect.DeepEqual(ka, kb) {
			return fmt.Sprintf("%s: keys %v vs %v", path, ka, kb)
		}
		for _, k := range ka {
			va, _ := x.Get(k)
			vb, _ := y.Get(k)
			if d := diff(path+"."+k, va, vb, ordered); d != "" {
				return d
			}
		}
		return ""
	case []any:
		y, ok := b.([]any)
		if !ok || len(x) != len(y) {
			return fmt.Sprintf("%s: %s vs %s", path, js(a), js(b))
		}
		for i := range x {
			if d := diff(fmt.Sprintf("%s[%d]", path, i), x[i], y[i], ordered); d != "" {
				return d
			}
		}
		return ""
	}
	if a != b {
		return fmt.Sprintf("%s: %s vs %s", path, js(a), js(b))
	}
	return ""
}

func js(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

func field(v any, path ...string) any {
	for _, p := range path {
		t, ok := v.(*Table)
		if !ok {
			return nil
		}
		v, _ = t.Get(p)
	}
	return v
}

func list(v any) []any { l, _ := v.([]any); return l }

func str(v any) string { s, _ := v.(string); return s }

func check(t *testing.T, what string, got, want any, ordered bool) {
	t.Helper()
	if d := diff("", generic(t, got), generic(t, want), ordered); d != "" {
		t.Errorf("%s: got≠js %s", what, d)
	}
}

func TestGoldenToml(t *testing.T) {
	for i, c := range list(loadGolden(t, "toml.json")) {
		in := str(field(c, "input"))
		got, err := ParseToml(in)
		if want := field(c, "error"); want != nil {
			if err == nil {
				t.Errorf("#%d %q: parsed, js failed with %v", i, in, want)
				continue
			}
			if err.Error() != str(want) {
				t.Errorf("#%d %q: error %q, js %q", i, in, err.Error(), want)
			}
			continue
		}
		if err != nil {
			t.Errorf("#%d %q: %v, js parsed it", i, in, err)
			continue
		}
		check(t, fmt.Sprintf("toml #%d", i), got, field(c, "value"), true)
	}
}

func rulesGeneric(rs []rule) []any {
	out := []any{}
	for _, r := range rs {
		t := NewTable()
		t.Set("starts_with", r.StartsWith)
		t.Set("fg", r.Fg)
		out = append(out, t)
	}
	return out
}

func mapGeneric(m map[string]string) *Table {
	t := NewTable()
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		t.Set(k, m[k])
	}
	return t
}

func TestGoldenPalette(t *testing.T) {
	g := loadGolden(t, "palette.json")
	pal := NewTable()
	for _, name := range paletteNames {
		pal.Set(name, mapGeneric(palettes[name]))
	}
	check(t, "palettes", pal, field(g, "palettes"), false)
	if names := field(g, "palettes").(*Table).Keys(); !reflect.DeepEqual(names, paletteNames) {
		t.Errorf("palette order %v vs %v", paletteNames, names)
	}
	for _, c := range list(field(g, "canonical")) {
		pair := list(c)
		var want any = pair[1]
		got := canonicalTheme(pair[0])
		if (want == nil && got != "") || (want != nil && got != want) {
			t.Errorf("canonicalTheme(%q) = %q, js %v", pair[0], got, want)
		}
	}
	configs := map[string]string{}
	for _, c := range list(loadGolden(t, "configure.json")) {
		if in, ok := field(c, "input").(string); ok {
			configs[str(field(c, "config"))] = in
		}
	}
	for _, c := range list(field(g, "themes")) {
		name := str(field(c, "name"))
		theme := themeFromHerdrConfig(configs[name])
		tt := NewTable()
		tt.Set("name", theme.Name)
		tt.Set("custom", theme.Custom)
		check(t, "theme "+name, tt, field(c, "theme"), true)
		resolved := resolvePalette(theme)
		check(t, "resolved "+name, mapGeneric(resolved), field(c, "resolved"), false)
		check(t, "rules "+name, rulesGeneric(paletteRules(resolved)), field(c, "rules"), true)
	}
	for _, c := range list(field(g, "builtins")) {
		name := str(field(c, "name"))
		resolved := resolvePalette(HerdrTheme{Name: name, Custom: NewTable()})
		check(t, "builtin "+name, mapGeneric(resolved), field(c, "resolved"), false)
		check(t, "builtin rules "+name, rulesGeneric(paletteRules(resolved)), field(c, "rules"), true)
	}
	for _, c := range list(field(g, "coloured")) {
		pair := list(c)
		if got := coloured(str(pair[0]), "x y"); got != pair[1] {
			t.Errorf("coloured(%q) = %q, js %q", pair[0], got, pair[1])
		}
	}
}

func TestGoldenSpecies(t *testing.T) {
	g := loadGolden(t, "species.json")
	for _, c := range list(field(g, "names")) {
		name := str(field(c, "name"))
		if got := slugify(name); got != field(c, "slug") {
			t.Errorf("slugify(%q) = %q, js %v", name, got, field(c, "slug"))
		}
		if got := defaultMon(name); got != field(c, "mon") {
			t.Errorf("defaultMon(%q) = %q, js %v", name, got, field(c, "mon"))
		}
		if got := isSpecies(name); got != field(c, "isSpecies") {
			t.Errorf("isSpecies(%q) = %v", name, got)
		}
		if got := float64(fnv1a(name)); got != field(c, "fnv") {
			t.Errorf("fnv1a(%q) = %v, js %v", name, got, field(c, "fnv"))
		}
	}
	for _, c := range list(field(g, "sockets")) {
		pair := list(c)
		if got := fmt.Sprintf("%x", fnv1a(str(pair[0]))); got != pair[1] {
			t.Errorf("socket hash %q = %s, js %v", pair[0], got, pair[1])
		}
	}
}

func agentEntryGeneric(e *AgentEntry) *Table {
	t := NewTable()
	for _, k := range e.Fields.Keys() {
		v, _ := e.Fields.Get(k)
		t.Set(k, v)
	}
	m := NewTable()
	if e.Match.HasAgent {
		m.Set("agent", stringsAny(e.Match.Agent))
	}
	if e.Match.HasProcess {
		m.Set("process", stringsAny(e.Match.Process))
	}
	if e.Match.Title != nil {
		m.Set("title", *e.Match.Title)
	}
	t.Set("match", m)
	return t
}

func stringsAny(l []string) []any {
	out := []any{}
	for _, s := range l {
		out = append(out, s)
	}
	return out
}

func agentTableGeneric(a AgentTable) *Table {
	t := NewTable()
	for _, g := range []struct {
		name string
		list []*AgentEntry
	}{{"agents", a.Agents}, {"programs", a.Programs}} {
		sub := NewTable()
		for _, e := range g.list {
			sub.Set(e.ID, agentEntryGeneric(e))
		}
		t.Set(g.name, sub)
	}
	return t
}

func TestGoldenConfig(t *testing.T) {
	for i, c := range list(loadGolden(t, "config.json")) {
		raw, err := ParseToml(str(field(c, "text")))
		if err != nil {
			t.Fatal(err)
		}
		cfg := resolveConfig(raw)
		want := field(c, "resolved")
		got := NewTable()
		got.Set("self", cfg.Self)
		got.Set("mon", cfg.Mon)
		got.Set("form", cfg.Form)
		got.Set("agents", agentTableGeneric(cfg.Agents))
		got.Set("sidebar", cfg.Sidebar.Table)
		check(t, fmt.Sprintf("config #%d", i), got, want, false)
		// Entry order decides matching.
		for _, g := range []string{"agents", "programs"} {
			if a, b := field(got, "agents", g).(*Table).Keys(), field(want, "agents", g).(*Table).Keys(); !reflect.DeepEqual(a, b) {
				t.Errorf("config #%d %s order %v vs %v", i, g, a, b)
			}
		}
	}
}

func paneMap(v any) map[string]any {
	out := map[string]any{}
	if t, ok := v.(*Table); ok {
		for _, k := range t.Keys() {
			e, _ := t.Get(k)
			out[k] = e
		}
	}
	return out
}

func TestGoldenAgents(t *testing.T) {
	custom, _ := ParseToml(str(field(list(loadGolden(t, "config.json"))[6], "text")))
	tables := map[string]AgentTable{"default": agentTable(NewTable()), "custom": agentTable(custom)}
	for i, c := range list(loadGolden(t, "agents.json")) {
		hit := classify(tables[str(field(c, "table"))], paneMap(field(c, "pane")), field(c, "proc"))
		want := field(c, "hit")
		if want == nil {
			if hit != nil {
				t.Errorf("#%d: %s, js no match", i, hit.ID)
			}
			continue
		}
		if hit == nil {
			t.Errorf("#%d: no match, js %v", i, field(want, "id"))
			continue
		}
		got := NewTable()
		got.Set("id", hit.ID)
		got.Set("kind", hit.Kind)
		looks := NewTable()
		for _, mode := range []string{"nerd", "text"} {
			l := look(hit.Entry, mode)
			lt := NewTable()
			lt.Set("glyph", l.Glyph)
			lt.Set("label", l.Label)
			lt.Set("colour", l.Colour)
			looks.Set(mode, lt)
		}
		got.Set("nerd", field(looks, "nerd"))
		got.Set("text", field(looks, "text"))
		got.Set("hide", truthy(hit.Entry.field("hide")))
		check(t, fmt.Sprintf("agents #%d", i), got, want, false)
	}
}

var goldenAnims = map[string]Anim{
	"full":     {"base": {"b"}, "bob": {"bob0", "bob1"}, "poison": {"poison0", "poison1", "poison2", "poison3"}, "sleep": {"sleep0", "sleep1", "sleep2", "sleep3"}, "sendout": {"out0", "out1", "out2"}, "recall": {"rec0", "rec1", "rec2"}, "tackle": {"tk0", "tk1"}, "harden": {"hd0", "hd1"}},
	"thin":     {"bob": {"x", "y"}},
	"baseonly": {"base": {"b0", "b1", "b2"}, "sleep": {}, "poison": {"p0", "p1", "p2"}},
}

func pickGeneric(r Pick) *Table {
	t := NewTable()
	switch {
	case r.Hold:
		t.Set("hold", true)
		t.Set("busy", r.Busy)
	case r.Shot != nil:
		shot := []any{}
		for _, s := range r.Shot {
			e := NewTable()
			e.Set("at", float64(s.At))
			e.Set("frame", s.Frame)
			shot = append(shot, e)
		}
		t.Set("shot", shot)
		t.Set("busy", r.Busy)
		entry := NewTable()
		entry.Set("name", r.Entry.Name)
		if r.Entry.Done == "" {
			entry.Set("done", nil)
		} else {
			entry.Set("done", r.Entry.Done)
		}
		t.Set("entry", entry)
		t.Set("end", float64(r.End))
	default:
		t.Set("frame", r.Frame)
		t.Set("busy", r.Busy)
	}
	return t
}

func TestGoldenAnim(t *testing.T) {
	g := loadGolden(t, "anim.json")
	for n, run := range list(field(g, "runs")) {
		a := goldenAnims[str(field(run, "anim"))]
		st := newAnimState()
		var results []any
		for _, op := range list(field(run, "script")) {
			o := list(op)
			switch o[0] {
			case "enqueue":
				done := ""
				if len(o) > 2 {
					done = str(o[2])
				}
				enqueue(st, str(o[1]), done)
			case "observe":
				observe(st, str(o[1]), o[2].(bool), o[3].(bool))
			case "pick":
				results = append(results, pickGeneric(pick(st, str(o[1]), a, int64(o[2].(float64)), o[3].(bool))))
			}
			s := NewTable()
			q := []any{}
			for _, e := range st.Queue {
				q = append(q, e.Name)
			}
			s.Set("queue", q)
			s.Set("parked", nullable(st.Parked))
			s.Set("wasBlocked", st.WasBlocked)
			s.Set("fresh", st.Fresh)
			if st.Shot != nil {
				s.Set("shot", st.Shot.Name)
			} else {
				s.Set("shot", nil)
			}
			results = append(results, s)
		}
		check(t, fmt.Sprintf("anim run %d (%s)", n, field(run, "anim")), results, field(run, "results"), false)
	}
	for _, c := range list(field(g, "rollup")) {
		pair := list(c)
		var in []string
		for _, s := range list(pair[0]) {
			in = append(in, str(s))
		}
		if got := rollup(in); got != pair[1] {
			t.Errorf("rollup(%v) = %s, js %v", in, got, pair[1])
		}
	}
	for _, c := range list(field(g, "boundary")) {
		pair := list(c)
		a := list(pair[0])
		got := nextBoundary(int64(a[0].(float64)), int64(a[1].(float64)), int64(a[2].(float64)), int64(a[3].(float64)))
		if float64(got) != pair[1] {
			t.Errorf("nextBoundary(%v) = %d, js %v", a, got, pair[1])
		}
	}
}

func TestGoldenNight(t *testing.T) {
	g := loadGolden(t, "night.json")
	for _, c := range list(field(g, "clock")) {
		r := list(c)
		at := time.Date(2026, 10, 1, int(r[0].(float64)), 30, 0, 0, time.Local)
		if got := byClock(at, r[1].(float64), r[2].(float64)); got != r[3] {
			t.Errorf("byClock(%v, %v, %v) = %v, js %v", r[0], r[1], r[2], got, r[3])
		}
	}
	t.Setenv("PATH", "")
	for _, c := range list(field(g, "plans")) {
		pair := list(c)
		sb := sidebarDefaults()
		in := pair[0].(*Table)
		if v, ok := in.Get("night_command"); ok {
			sb.Set("night_command", v)
		}
		p := nightPlan(Sidebar{sb})
		got := NewTable()
		got.Set("mode", p.Mode)
		if p.Mode == "command" {
			got.Set("command", p.Command)
		}
		check(t, "plan "+js(pair[0]), got, pair[1], false)
	}
}

func TestGoldenProcs(t *testing.T) {
	g := loadGolden(t, "procs.json")
	projects, _ := filepath.Abs(filepath.Join("testdata", "projects"))
	fw := field(g, "frameworks").(*Table)
	for _, dir := range fw.Keys() {
		want, _ := fw.Get(dir)
		got := frameworkFor(filepath.Join(projects, dir))
		if (want == nil && got != "") || (want != nil && got != want) {
			t.Errorf("frameworkFor(%s) = %q, js %v", dir, got, want)
		}
	}
	fix := func(p string) string {
		if p == "" {
			return ""
		}
		return filepath.Join(projects, p)
	}
	table := agentTable(NewTable())
	for i, c := range list(field(g, "describes")) {
		pane := paneMap(field(c, "pane"))
		for _, k := range []string{"foreground_cwd", "cwd"} {
			if s, ok := pane[k].(string); ok {
				pane[k] = fix(s)
			}
		}
		var proc *Proc
		if p := field(c, "proc"); p != nil {
			proc = &Proc{Pid: int(toNumber(field(p, "pid"))), Name: field(p, "name"), Cwd: fix(str(field(p, "cwd")))}
		}
		d := describe(table, pane, proc, str(field(c, "glyphs")))
		want := field(c, "desc")
		if want == nil {
			if d != nil {
				t.Errorf("describe #%d: %+v, js null", i, d)
			}
			continue
		}
		got := NewTable()
		got.Set("id", d.ID)
		got.Set("kind", d.Kind)
		got.Set("hide", d.Hide)
		got.Set("glyph", d.Glyph)
		got.Set("label", d.Label)
		got.Set("colour", d.Colour)
		check(t, fmt.Sprintf("describe #%d", i), got, want, false)
	}
	for _, c := range list(field(g, "neovimLabel")) {
		pair := list(c)
		var info *nvimInfo
		if in := pair[0]; in != nil {
			info = &nvimInfo{Cwd: fix(str(field(in, "cwd"))), Filetype: str(field(in, "filetype"))}
		}
		got := neovimLabel(info, "")
		if (pair[1] == nil && got != "") || (pair[1] != nil && got != pair[1]) {
			t.Errorf("neovimLabel(%s) = %q, js %v", js(pair[0]), got, pair[1])
		}
	}
	wantIcons := field(g, "icons").(*Table)
	for _, k := range wantIcons.Keys() {
		want, _ := wantIcons.Get(k)
		w := list(want)
		if got := icons[k]; got.Glyph != w[0] || got.Colour != w[1] {
			t.Errorf("icon %s = %+v, js %v", k, got, w)
		}
	}
	if wantIcons.Len() != len(icons) {
		t.Errorf("%d icons, js %d", len(icons), wantIcons.Len())
	}
	ft := field(g, "filetypes").(*Table)
	if ft.Len() != len(filetypes) {
		t.Errorf("%d filetypes, js %d", len(filetypes), ft.Len())
	}
	for _, k := range ft.Keys() {
		want, _ := ft.Get(k)
		if filetypes[k] != want {
			t.Errorf("filetype %s = %q, js %v", k, filetypes[k], want)
		}
	}
	if nvimExpr != field(g, "nvimExpr") {
		t.Errorf("nvim expr differs:\n%s\n%v", nvimExpr, field(g, "nvimExpr"))
	}
}

func TestGoldenOrder(t *testing.T) {
	for i, c := range list(loadGolden(t, "daemon.json")) {
		var panes []map[string]any
		for _, p := range list(field(c, "panes")) {
			panes = append(panes, paneMap(p))
		}
		ws := []any{}
		for _, w := range workspaces(panes) {
			e := NewTable()
			e.Set("id", w.ID)
			ids := []any{}
			for _, p := range w.Agents {
				ids = append(ids, p["pane_id"])
			}
			e.Set("agents", ids)
			if w.Head != nil {
				e.Set("head", w.Head["pane_id"])
			} else {
				e.Set("head", nil)
			}
			ws = append(ws, e)
		}
		check(t, fmt.Sprintf("workspaces #%d", i), ws, field(c, "workspaces"), true)
		sorted := append([]map[string]any(nil), panes...)
		sortPanes(sorted)
		order := []any{}
		for _, p := range sorted {
			order = append(order, p["pane_id"])
		}
		check(t, fmt.Sprintf("order #%d", i), order, field(c, "order"), true)
	}
}

func TestGoldenManaged(t *testing.T) {
	configs := map[string]string{}
	for _, c := range list(loadGolden(t, "configure.json")) {
		if in, ok := field(c, "input").(string); ok {
			configs[str(field(c, "config"))] = in
		}
	}
	for _, c := range list(loadGolden(t, "managed.json")) {
		name := str(field(c, "name"))
		text := configs[name]
		before, block, after, ok := splitBlock(text)
		split := []any{before, nil, after}
		if ok {
			split[1] = block
		} else {
			split[2] = ""
		}
		check(t, name+" split", split, field(c, "split"), true)
		if got := withoutBlock(text); got != field(c, "without") {
			t.Errorf("%s withoutBlock:\n%q\njs:\n%q", name, got, field(c, "without"))
		}
		a, s := taken(text)
		tk := NewTable()
		tk.Set("agents", a)
		tk.Set("spaces", s)
		check(t, name+" taken", tk, field(c, "taken"), false)
		theme := themeFromHerdrConfig(text)
		b := buildBlock(text, resolvePalette(theme), theme.NameString())
		wb := field(c, "build")
		if want := field(wb, "block"); (want == nil) != !b.HasBlock || (want != nil && want != b.Block) {
			t.Errorf("%s block:\n%s\njs:\n%v", name, b.Block, want)
		}
		if b.Snippet != field(wb, "snippet") {
			t.Errorf("%s snippet differs", name)
		}
		check(t, name+" skipped", stringsAny(b.Skipped), field(wb, "skipped"), true)
		ent := NewTable()
		for _, e := range b.Entries {
			ent.Set(e[0], e[1])
		}
		check(t, name+" entries", ent, field(wb, "entries"), true)
		if got := applyBlock(text, b.Block, !b.HasBlock); got != field(c, "applied") {
			t.Errorf("%s apply:\n%q\njs:\n%q", name, got, field(c, "applied"))
		}
		if got := applyBlock(text, "", true); got != field(c, "removed") {
			t.Errorf("%s remove:\n%q\njs:\n%q", name, got, field(c, "removed"))
		}
	}
}

// TestGoldenConfigure runs the configure command on every sample config
// with every flag set, in a scratch directory each, exactly as the
// generator ran the Node version, and compares stdout, stderr, exit code,
// the resulting file and the backups.
func TestGoldenConfigure(t *testing.T) {
	for i, c := range list(loadGolden(t, "configure.json")) {
		dir := t.TempDir()
		file := filepath.Join(dir, "sub", "config.toml")
		input, hasInput := field(c, "input").(string)
		if hasInput {
			if err := os.MkdirAll(filepath.Dir(file), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(file, []byte(input), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		var flags []string
		ok := false
		for _, f := range list(field(c, "flags")) {
			if f == "ok" {
				ok = true
				continue
			}
			flags = append(flags, str(f))
		}
		herdr := filepath.Join(dir, "fakeherdr")
		script := "#!/bin/sh\necho \"  no server running \" >&2\nexit 1\n"
		if ok {
			script = "#!/bin/sh\nexit 0\n"
		}
		if err := os.WriteFile(herdr, []byte(script), 0o755); err != nil {
			t.Fatal(err)
		}
		t.Setenv("HOME", dir)
		t.Setenv("XDG_RUNTIME_DIR", dir)
		t.Setenv("XDG_CONFIG_HOME", filepath.Join(dir, "cfg"))
		t.Setenv("HERDR_BIN_PATH", herdr)
		var stdout, stderr bytes.Buffer
		code := cmdConfigure(append(flags, "--herdr-config", file), &stdout, &stderr)
		name := fmt.Sprintf("configure #%d %s %v", i, field(c, "config"), field(c, "flags"))
		if got := strings.ReplaceAll(stdout.String(), file, "$FILE"); got != field(c, "stdout") {
			t.Errorf("%s stdout:\n%s\njs:\n%v", name, got, field(c, "stdout"))
		}
		if got := strings.ReplaceAll(stderr.String(), file, "$FILE"); got != field(c, "stderr") {
			t.Errorf("%s stderr:\n%s\njs:\n%v", name, got, field(c, "stderr"))
		}
		if float64(code) != field(c, "code") {
			t.Errorf("%s exit %d, js %v", name, code, field(c, "code"))
		}
		var result any
		if b, err := os.ReadFile(file); err == nil {
			result = string(b)
		}
		if result != field(c, "result") {
			t.Errorf("%s result:\n%v\njs:\n%v", name, result, field(c, "result"))
		}
		backups := 0
		entries, _ := os.ReadDir(filepath.Dir(file))
		for _, e := range entries {
			if strings.HasPrefix(e.Name(), "config.toml.bak.") {
				backups++
			}
		}
		if float64(backups) != field(c, "backups") {
			t.Errorf("%s: %d backups, js %v", name, backups, field(c, "backups"))
		}
	}
}
